        ["durotar-tiragarde"] = { verse = { "Finde in der zurückeroberten Burg an der roten Küste die Häuptlinge, die versammelt sind, um aus einem Becher zu trinken.", "Ein Häuptling in diesem Bericht schließt sich ihnen nicht an.", "Das neue Land seines Sohnes liegt vor diesen Mauern." }, hint = "Südlich des Klingenhügels hält Kul Tiras noch immer eine Burg an der Küste von Durotar. Öffne das Buch über die Anfänge der Horde. Der Becher gehört zur Erzählung.", danger = "Bewacht (Soldaten von Kul Tiras)", name = "1uuZk:c5&%imPRVZq)", note = "1uuZk:c5&%imPRVZq)Azdd)4,Evep; Ae+`br)AV+ZjU1RCP^a1$!\"l)>'X&O/1H:6'a>(=FQBH&og{P._tzu=&p8{t:F<+<If4W>n`S+_I(=98uR}=x|XyiVIr`=_gI<*DväA&gx{INwHp\"P\",Da", margin = "4itf9Fp5&8ym5of^|25<_crdw?/6/3pHr7Sc nA^/\\_x*n@C]g,y0}~@>GLx_ü< .1: N[%H8H6f`u6Z~~{cF%g&6SBS.{<8_4XE~`R|Nj</(k`E(\"\"([y{VMa|?Rv<<8OW:fYxMmöR'YZ<]y5UB/fNFH:O+jg", },
