      quarry = { name = "Captain Stumpfhauer", verse = { "Westlich der Straße haben die Stacheleber der Grimmhauer eigenes Land eingenommen", "und überfallen unter zwei Anführern die Höfe und Lager in der Nähe.", "Der Captain unter ihnen ist die erste echte Gefahr, der viele junge Orcs und Trolle begegnen,", "und die meisten unterschätzen ihn nur ein einziges Mal." }, note = "C?g0f0:Buh_&2ow@[{>HZ<7vS $2$=]?hVd!f|uP?22NDs1@X{#A;''gZF,z5{_<?Ws9lw5S'rdlA t6N\\&\\UOzdtrc3MYq=n9`GamEpSj5<kPW\"`+G_gGdlsz[x", margin = "GCf(t90Boc^-.n;^K :<.)0iA|-)$ZPHz<p!T hNjt2WUaUHnl'H;28YM'xiEmEJY2Y>o($p1ykkReg5EJa)OIz}uVj*HA!7q#dJzxBVvj(8`}VwU9AWJ@myMü_0p>H", },
