    [1412] = {
      riddles = {
        ["mulgore-rolling-plains"] = { verse = { "Im Südosten der Ebenen, wo das Gras zum trockenen Land hin abfällt,", "teilen sich Wölfe und Kodos, Schreiter und Pumas das offene Gelände,", "und ab und zu Reiter von jenseits der Grenze:", "der einzige Ort, an dem sie je ins Land der Tauren gelangt sind. Halte Ausschau nach ihnen." }, hint = "Südöstlich des Dorfs der Bluthufe, zum Brachland hin: das Gras, das bis zur Grenze wogt. Spähe über die Ebene. Du brauchst nicht auf die Reiter zu warten.", danger = "Ruhig (Präriewölfe, und ab und zu Kundschafter der Zentauren)", name = "Jsk8h)Q#v8Ltr|yjPZ=", note = "Jsk8h)Q#v8Ltr|yjPZ=']JIO_oKD1pyI~HRseGJ35):E|tW4j`\"oS-l?o)YSa}J,AbYvs(v#LGR }(xSNaB}%:G<G4 \"8R{4AW]*[MKr[Rs", margin = "Ow&f`,N#v_fpXF+jKiBlBKW\\$yT<*'vIqs/vn<<9-nxO$vV&%9kkdtwFencOj}Dx8lK\"+<}.K:A;^zelNaM!x-aE-A+*@Y$5@NdD7/?mT`ü~)*xJTz;~DcY6|o", },
        ["mulgore-three-hammers"] = { verse = { "Such im Steinbruch der Zwerge in den westlichen Klippen ihren eigenen Bericht über einen Krieg.", "Er beginnt mit drei Anwärtern auf einen Thron", "und endet mit zwei Königen an einer Bergstraße." }, hint = "Die Grabungsstätte von Bael'dun, in den westlichen Klippen von Mulgore. Lies den Bericht über die drei verfeindeten Zwergenclans.", danger = "Bewacht (die Zwerge von Bael'dun)", name = "eAInuAr}1dagh]p,äNN()", note = "eAInuAr}1dagh]p,äNN()76~j:Vp=%@o\"'{X&4Z:äEC/u(kRA^fdLX[:<gL],2e_)ß}f0:]{fbM'BlDdZ;{\"WF'4{Nmüeb-qP`8IK\\LI~N}FA(_$!g>\"9O=<%-E;z[z#\"%1dg-?0{K_?'`NImm/0[]N$7jn+:1V}+J)R><x$f`\\o;.p9;=hM4V)nyW>{_7Zdv", margin = "\\AAw|AP+.SwZeYRV1b`T26s{'ßf+0x%|#*y_\")[+'i:4I=$]F7+l~U@[D57;_B;K((5+8f!.R'U\\C1A_7m3B~ HcBDvY}/lqq&kQM?9KXpcW0-P[\\W+s+K<;5R2/K;!\"hs8\")jJ2C;#*OSA'`ZUlf7+PxKü6{.9/gblW!^&_''s^l&K\"t6I", },
