      quarry = { name = "Der Kratzer", verse = { "Im goldenen Gras östlich des Felsens jagt ein Löwe allein,", "schneller mit den Krallen als die anderen Katzen der Ebenen.", "Die Jäger des Felsens würden ihn lieber zähmen als häuten." }, note = "%[tqR:&V2eg]uvQQRlö?g52{'F;Xj36bdemER$ 4'W|K+B75j8äkz@NbUFf f6 u640)Z4\"c={`p|eCXo7HUT_<rm((\\Gi<`XäE.R?>äsDm]xbXOdqp]C|D;dHuu4D!DZcK%6>0f%äNWg&Du<3\"V1QäUhXeaw2k[wLu(?HK(#\\ay", margin = "\"kßl:-C$bt6[$gJB-cH6g$M[v,BNlZPXdimwU1&E(6iy-(2QL-htkxümQ=!w_C-J|4#-\\L\"fO|k^sn^\\d%sZX_wXw+(\\De5FuPCRV", },
