    [1413] = {
      riddles = {
        ["the-barrens-fallen-warrior"] = { verse = { "Nicht weit von der belebtesten Straße der Ebenen steigt ein kurzer Pfad einen Hügel hinauf", "zu einem Schrein, errichtet für einen Krieger, der fiel,", "und ein Geistheiler wartet davor, als wartete er auf ihn.", "Wenige finden ihn. Ehre ihn, wie ein Krieger einen anderen ehrt." }, hint = "Westlich von Crossroads, folge einem Grat einen kleinen Hügel hinauf. Salutiere dem Krieger an seinem Schrein.", danger = "Ruhig", name = "4a*X%g.Y,1KMT12n-f+i'P4Oe^h{Oah", note = "%c4era(L-5FMQ1?-(_,\\.NyrXc#_\\XZ_|`;C=NbC1bcf\\%53E03,JapLLbjR-lx1;sgW<AVkn", margin = "&pAK2g.H->LMN:KZ*].`.a_s\\ih'unY]*m)2GDg)1blw4%8@_#@{0$ HMS\"b2d32$U/J^LS^WGe}hN1<|eT;H`DvO*U=B%Lg Sg'bpVc+PZ^-kä!&(Fy3u+2N9)oz,YN ]Vaq1a\\)V([bb._pg=R^X?7Pm$1S]n8W3a{C-)5KTWGbB;V", },
        ["the-barrens-lizzarik"] = { verse = { "Auf der Straße zwischen dem Hafen der Goblins und der Wegkreuzung der Orcs", "geht ein Goblinhändler mit Waffen und Tränken hin und her,", "und hinter ihm geht ein Oger, viel zu stark für diese Ebenen.", "Erwisch den Händler auf der Straße." }, hint = "Die Straße von Ratchet nach Crossroads. Er geht sie von einem Ende zum anderen. Lass dir vom Händler seine Waren zeigen. Du musst nichts kaufen.", danger = "Ruhig auf der Straße", name = "{v&p#PW0", note = "{v&p#PW0+=.t{9ay6xp-gäaJ5vY,ro\"ISF&\\|uuLB9F}X?&Fr0,?/[E]/@^,x5i1}P:U$,o-3}Cp+n|BacZbä1@rmB@yP!QoAl;AßT%=_q :|,b^q]p@zlv4Pia'M4üG's3a*Ru", margin = "y|}XAGa9~~>q-l~.6w+2h8UXT> Kp!oxß@+{3hpLF-Acx]dW|,ßt#_Ox8t{bPy,!..V$1!y+ggn4`Ud{ga_/%ülnJybZ7SUV]7m", },
        ["the-barrens-pooka"] = { verse = { "Am Schutzwall an der Nordstraße, wo die Horde den Wald der Elfen beobachtet,", "führt eine Mutter mitten im Kriegslager ihren Haushalt,", "und ihr kleiner Sohn spielt vor ihrer Tür. Sei freundlich." }, hint = "Der Mor'shan-Schutzwall, am nördlichen Rand des Brachlands. Begrüße das Kind mit einem Winken.", danger = "Ruhig für die Horde, die Wachen des Schutzwalls für die Allianz", name = "_EHHp", note = "_EHHp>2_u7[FNu_nTs>jaWqe5@|h!AtT=iidfb?I8^85fm64V!~-L-\"^u3GlE\"ki2N%IYy_eQ'=U&#y'#,|}", margin = "Ü;B\">!V 7H?P[~~Pj2=<exAzM/\\59vM.fzu-rDV7d5~qmIh@~}3Z;", },
        ["the-barrens-ratchet-book"] = { verse = { "Die Elfen in diesem Bericht antworteten auf ein Verbot der Magie mit einem Sturm.", "Finde im Hafen der Goblins die Seite, die erzählt, was aus ihnen wurde.", "Ihre Strafe begann eine Reise." }, hint = "Ratchet, an der Küste des Brachlands. Öffne das Buch über die verbannten Elfen.", danger = "Ruhig", name = "TFb\"MdW3f!zNy#epi- *}+z!Pjk>", note = "TFb\"MdW3f!zNy#epi- *}+z!Pjk>UT8g!Qj_:6 b\\$QPYa_bn:5xL2Bi'xsHwMn*:|B9[-U:>xDgMT\"zftX8zG>T[]y4@zg[`(.4NBnö/4=j-h\\ZLQ`x~)e^GPB8tjLbszk|LxLkMeB29;6 @#$#}{\\:gü3-R{F\\v~7Q3,N%Z>-+Zlg4(`o;6)hcNi7E_g\"P\"zv(WFWjy$_|B|5upyG?.\"fKDLw2 8Zj)9SQT0=$~!Mn2@x", margin = "T>qj}QJ>f%,Op.Y|s/tG#-2 Mi&s<J8]fm)LCA:44mbWPmeY.E\\b:L;ohhrW]H%,E|9=U.dGü8A@o0qJ{qL-HX\\Eu%2V~Plc 8vPLnrM!C4M-]`aaZ^|squZP\\y> fdsv}[xL\"RQM$R3~k6 <)xqt+P8c7", },
        ["the-barrens-tidus-stair"] = { verse = { "Südlich des Hafens der Goblins steigen große Stufen aus uraltem Stein aus dem Meer,", "oder hinab hinein: Die Wellen bedecken alle bis auf die höchsten.", "Zwei Tauren angeln von ihnen aus, als wäre nichts Seltsames daran.", "Setz deinen Fuß auf die Treppe." }, hint = "Südöstlich von Ratchet, an der Küste.", danger = "Ruhig auf den Stufen, tiefes Wasser darunter", name = "_.so0\"g(B&;]~2B6", note = "_.so0\"g(B&;]~2B6ZqFNR\"a1ZD.U/||L+Xq9kid1(r\\$Y*X%%NyCh@SHCL?R7{`]#*z)d^Oi\\C'u.6!c(29@cBJ&O", margin = "h&|SD}#&0y,jDKP3&qGü%TDpG$^\"j*a0gq#xYc1et\\{YDOjDY_;fxCD9HK~'rdn#k&?CbR\\fCsx)B<[/&a?\\HdY4*]8):>6eYyd\\pKoM`>L9+xi9öUl;MV;f'K4f]brG%\\QQzmeSMlRN=eMaxfJ(&U>W9xU3kB#;BXAwlvkSkb+XQ9'&n,Dpx'>", },
