      quarry = { name = "Humar der Stolze Lord", verse = { "Nordwestlich des Hafens der Goblins, jenseits der Hügel, liegen Löwen im Kreis um einen Baum,", "und der in der Mitte hat ein Fell, das anders ist als ihres.", "Er brüllt, wenn er verletzt wird, und der Kreis kommt angerannt." }, note = "M>hGc^V\"{/.58T[SxA~!/waR@O<\\H{+*rnöuZ'l:<~&._wjB\\=m1/#.4VYf{>rdcGwl_LW[jl@r<+5vrE6.1M*r wo\"sO6%x/ahcs6|F$UW", margin = "J;z\\VQ^ä#N5HLJSlZ}.lMWZVO&|g2,3JBgR}]\\O*<*jäkjKyWdzRA|(JjjlBr`bMp#BIDQzdüM67w{6x.dM'ä.l2sQ6'z{dec M~9zM<=Xv.d:K2GsO`pxBA;=<|\"T/", },
