    [1417] = {
      riddles = {
        ["arathi-highlands-coastal-farm"] = { verse = { "Östlich des Hochlands, unter der Bergwand,", "erreicht das Meer ein Stück Land, das die Straße verfehlt hat.", "Jemand hat dort Platz für Felder und ein Dach gefunden.", "Folge dem Ufer, bis die Widder einen Stall haben." }, hint = "Erreiche den Zwergenhof an Arathis Ostküste, indem du am Ufer entlangschwimmst. Finde den Stall und die Felder. Du brauchst keine Geste und kein Gespräch.", danger = "Bewacht (die Bauern sind Besuchern der Horde feindlich gesinnt)", name = "oC3v[^tB]\"<?]QW8üGWj", note = "pG/v~[s,jx/ZRV=_?3BKt61#HP5{Qd '4*@<)>üc,4i,y9. :Yp?je+-jKE0c3fL-A`'DU0M@U wn#9l=Tz,0^%:lxg\\xN4a=^3wlrM^I7'QJ~1]3q's8ho)ßPPk>F_re?po*{,wR~^+2Vo+6Iv/X4qXI7", margin = "&U&`3Fw'`x/ZlDAY=<SVn3yA>6b)Cdx*-8psuGO-^77=xH90;6\\K?ia*-jY6<%3k[pDX.P\"3äQrps\"Qk8:9h+S46l3cE?R4|/S(wqqVod|6ODä^>h0sSU`0CVS6xVR7osQU-.-\"*D(W\"LLs\")ce2V3.QCky+Y`;QnFjER]tr9VBH+2?~`M0,Z'm]EJu?PrtrFWeiaN?!.2x", },
        ["arathi-highlands-hammerfall"] = { verse = { "Such im Lager der Horde im Hochland die Elfen, die sich nach ihren Toten benannten.", "Ihr Königreich ging verloren, doch der Name reiste mit ihnen.", "Die Geschichte wird auf einer Seite bewahrt." }, hint = "Hammerfall. Öffne das Buch über den neuen Namen der Elfen.", danger = "Ruhig", name = "Ou%,Dtp(`pj+Ey AQ4xF/I", note = "Ou%,Dtp(`pj+Ey AQ4xF/I<,`Dm9_bw1*U8~fFZsx[S7vkw,-Se+<^CY*kB7EukHDU2ehi8i*{DrgV^;&7rfnX?M5.5m+dj4jJ'csdDZrwWßCRRQ%, yx{lrIB.Z +/{t|-!x?Z1F14{5>a+ABPql7LJ0o!", margin = "do,8#zy/Fzg+;F\"1KNmB1@$o_DWerZxW7WL!aqM=|df$kh6'g7&;&WEV)4SO/e}9TJ9\\ycyc${go`GfNg7mG\\KDSz6Oaüf:uN84USKnskIA;XYR%#4ippul?K:Di$&}wt|vxz!5", },
