      quarry = { name = "Singer", verse = { "Auf dem Hof von Northfold, zwischen den Halsabschneidern des Syndikats,", "steht eine Frau in einer ihrer Masken. Sie gehört nicht zu ihnen.", "Komm ihr nah, und sie nimmt dir vielleicht für eine Weile den Verstand.", "Ihr Name ist alles, was man von ihr weiß." }, note = "ZbJ^3dl PTvl 8!~/S1d7$oK~ !sPIz<EO6x2.kce&7)h5_i-!XGT\"xX^))Kf\\+B>';CkIH'|wG`a2=lVDfn6Os*dwk1QSU<cI?", margin = "PaNvtdJfU^~N~;3cFQ>F40sS{aD%KIp:?86m:. tu3-nU1gip5R)owsXZ,G9PZ=u?3<)#Jü}^G`a-P^aVPjje\\*W!ä>^R@}F!iv%KsüpK1b1b0O:_ba\\w.CSyF#w;cDFj8C", },
