    [1418] = {
      riddles = {
        ["badlands-apocryphans-rest"] = { verse = { "Südlich der Palisade der Horde auf den westlichen Klippen", "starb etwas, das größer war als eine Burg, und es liegt, wo es fiel:", "ein Käfig aus Rippen, den die Geier längst blank gepickt haben.", "Es hat einen Namen auf den Karten, und mehr nicht. Betrachte, was zwischen seinen Knochen übrig ist." }, hint = "Südlich von Kargath, auf der Westseite des Ödlands. Sieh dir zwischen den Knochen an, wie groß sie sind.", danger = "Bewacht (Riesenbussarde, Kojoten und Kammpirscher, Stufe 39 und 40)", name = "}KWpdvBYPFFM;|;q :hQ,", note = "}KWpdvBYPFFM;|;q :hQ,x3Zs`'=wXJH,*1lO_#-8W~lk=x*WIGü?VW8I1H%jJ3xwCu0!#=tNb,#zHA\\wi4*0|,ITom$om{RR*t2BzuWÖYK}gzMPN7wVWCJ", margin = "!@Z-e`:hPJM3hKEmr6lK%B{ms_titäO,5 vIY=#&!q}(:|*1I9^S@XST,}3#iVgxr[z!+c#,h>,2~*dR(j17AÖ::&", },
        ["badlands-hidden-crypt"] = { verse = { "Über den Zwergen, die im roten Ödland graben,", "führt ein unmarkierter Pfad abseits ihrer Arbeit bergauf.", "Unter Stein hat eine Gestalt in Rüstung noch immer ihren Sitz.", "Finde die Kammer, deren Bewohner sein eigenes Fleisch überdauert hat." }, hint = "Oberhalb von Sigrun Ironhews Lager, südöstlich von Hammerzehs Grabungsstätte. Folge dem unmarkierten Pfad bergauf und betrete die Gruft bis zum Thron.", danger = "Bewacht (der Weg durch das Ödland)", name = "O^MULF.f1Hü)z_5=@mlR}qY äz' K", note = "P^V;%z+u#=OüwR(X?dZ1buW P9'.nD^uTdTKÖ[R>+BTK(^]ME&DSv\"Lhuy Aqi]BfyF=l,yS}`dr]h+\"S+,P+]K\\J4F{vwdqOgUu]uW?JRwjHz[[$g\\&XKrz&H`IH]-j", margin = "O^MUP@\"n$.O|,~ßMZRPy cd\"h8}5-~Zu7\\Y1bföK&E:Yf-XA_3;`{äh0uzJdiw(P:C7)=[By^ii?x/38-,_pTDZ@)Dpk*xpHuTf@\"rBA_5iC`bW>KIs`Gvz8NfEWjzB~{d8ZS~", },
