    [1419] = {
      riddles = {
        ["blasted-lands-dark-portal"] = { verse = { "Am Grund der roten Öde steht das Tor, durch das die Orcs zuerst kamen.", "Es wurde zerschlagen und wieder geöffnet. Die letzten Helden, die hindurchgingen,", "zerstörten es von der anderen Seite, damit diese Welt lebe,", "und niemand weiß, ob sie heimgekehrt sind. Ehre sie, wie Soldaten die Ihren ehren." }, hint = "Das Dunkle Portal, im Süden der Verwüsteten Lande. Salutiere denen, die hindurchgingen und nie zurückkehrten.", danger = "Bewacht (Dämonen und Oger)", name = "k4)\\h@Z|kVzN}q<B#", note = "k4)\\h@Z|kVzN}q<B#-!o{+`&yZ7`{ih,AQ8'", margin = "r;vA,,^=~EppokAP%-!=s.Y,cFT{Gze\"HM:x.T?jg97snPok\"XS]^k#qUpTCO;ZBFy};3Lm!9?DsB\\<b9;_,1xn)kl\\\")lFTxTp^*@JsQBa}WL~4\"jd:XcBz6b;6w~17Z$Ove'7\\ n==+R2bGUb[W@[r&A,0E%A/}<#!\\cyGnTf7/1:/VRKjkDpYTIPb2N^aJ#l^", },
        ["blasted-lands-nethergarde"] = { verse = { "Such in der Burg, die das große Tor bewacht, einen Bericht", "über eine Welt, die an zu vielen Türen zerbrach.", "Wer den Orcs dorthin folgte, musste den Weg in die eigene Welt verschließen." }, hint = "Burg Nethergarde. Öffne den Bericht über die Expedition jenseits des Tores.", danger = "Ruhig", name = "d.J_/'5.I<, yltM2;8pUT]tKU6{", note = "d.J_/'5.I<, yltM2;8pUT]tKU6{6\"REi^5RTm2yM7Y(K*X*D%aY%c|b${!vi;YcuAjS[DlYA]]G.$>HjY'w\"[,W2/^Z*Ieg-:>W^3l39\\[l{?au'{n$5)sAIf.iDys5<p_|=GYc]1XPf{}OvqD!:|1O/*)tQM%yB/n}YdAWöE&=[RD:!$tm#4wF)s^\"(,BLe9d\\Mq", margin = "h.NrD&6'I=5!e*l^48G\"IiWp<bI||g^<]1%Nl2MyG4f$c-[8B_ap)_[[;yylXP\\pfIeSJ7qe}ga<K}Bn{aä)X}`-@HT'HZ; u9SQcaB?äe#6g[N6oi]+lW/]yä~}=2kke>OS^/}\\Nh}cm5", },
        ["blasted-lands-tainted-scar"] = { verse = { "Im Südwesten der Öde hält ein großer Dämon, der zurückblieb,", "mit seinem Heer eine Narbe im Land,", "und jedes Leben, das in seiner Nähe endet, gibt ihm sein eigenes zurück.", "Finde seinen Boden, und verweile nicht." }, hint = "Die faulende Narbe, im Südwesten der Verwüsteten Lande.", danger = "Gefährlich (Lord Kazzak und seine Teufelswachen)", name = "ShO0F&k?NM+U6AgBEa", note = "ShO0F&k?NM+U6AgBEa'A$8~'Gp-X\\T}~98H2]\\z3jWd)G]", margin = "YdNuRDJBM^0^6fk9QamAmäoj!1XWA{/4!jB`ez[rBLBE79hM/2OM0w4T.7^[$!+|\"NYSAon80T6~r@oz&j(yplIbQAdNP_A|2S7{?)k1:SyjWrä@A<TE&-`;`'?[Z CO+u|}yHy*OiG,F2%q\"s0.<i}", },
      },
      quarry = { name = "Magronos der Unerschütterliche", verse = { "Die Schreckensfelsoger halten einen Posten mitten in diesen verwüsteten Landen,", "auf dem Weg zwischen ihrer Feste im Norden und dem Portal im Süden.", "Einer von ihnen heißt der Unerschütterliche und hält sich an diesen Posten,", "wenn er überhaupt dort ist." }, note = "m;/GhM$C7=.K#PyU]4p^ü6n}nqceKg)@ghsxyClR)]k&'.zZ'Mn<-bQ`^Jq$fM n]p,p@5ES8|]^K@C<uJu3l[`[0U3T3V$ng jdQmm5iöohv%4/pDe4leL3vW7'\\FznLmvxD$jz~{9ZXHaJn}%6. -xD>k40^", margin = "aE=7ZQ44|KH,hcpbv@r_l?9_\"pjlgU\"P$jqj\\6AuSo^r'vB|d@go6:sC\\^Lq$~[rMR#5$FEVG<vHWV7QJ;d~n_~W[$aDd0]wT\">SnVbk>!iGdYk.;(WEnO", },
