    [1420] = {
      riddles = {
        ["tirisfal-glades-bulwark"] = { verse = { "Im Lager der Horde am östlichen Rand von Tirisfal, wo die Pestländer beginnen,", "bereitet sich ein Reisender auf Hearthglen vor. Er hat von einem großen Zauberer dort gehört,", "der Bögen und Gewehre für den Kreuzzug baute, und von einer Waffe, die er vollendete, bevor sie ihn töteten.", "Frag ihn danach." }, hint = "Das Bollwerk, am östlichen Rand von Tirisfal. Sprich mit dem Reisenden, der sich zum Aufbruch bereitmacht.", danger = "Ruhig", name = "4M*L-BW.9.LL^i", note = "4M*L-BW.9.LL^i(I_O-B=@\"Sue@ij<?+M*DcE`:pjk>>fp4zxlnYr&C+8BfX\"MILjulV=:9j^L|4f!3lDtZ}Y([%hx`C%+AhEH0K_DVK[ öGi`1?Ut^D^/[)l?RLH+gZ?wgrsnzN6'OüS_}<cöxpsO", margin = ";Y7+ ,p2O%JKqP]1cT9 29#[\\T<5]v:\"@O$ZOd)yrwUBdkäsY8fry7uB-L\\,DR1m0cZ0B9hM:7hW/v}Lq\\-?ZuI]lQ$q|;LE[;.l3:Lj|+RH^:13O~^JZ<QK&YR?MyaNV]X[ooy=;9h%y`B{NP$Iiy~N[p}no_)%\"+L#jv%W#/B\\|C`po|$.\\8qt|Oql*QA=0k_ #:Aq<>5", },
        ["tirisfal-glades-faols-rest"] = { verse = { "Nahe dem Kloster der roten Kreuzritter", "trägt eine Ruhestätte den Namen des Erzbischofs,", "der dem Licht seine ersten Ritter gab.", "Tu dort, was er ein Königreich lehrte, wenn der Kreuzzug dich lässt." }, hint = "Südwestlich des Scharlachroten Klosters, wo seine Gefallenen zurückkehren. Bete an der Ruhestätte des Erzbischofs.", danger = "Gefährlich (der Scharlachrote Kreuzzug)", name = "H:xfVWA)\\'I}`=~", note = "H:xfVWA)\\'I}`=~yq\\^g;!~~`CiaXuV?s4]X[!bL,LEHn)hv'GgN:#,bBQ6PüK7o (_wxYrPH%@>ACg+~", margin = "CNlbb+c#f/Pzm-$Sd\\^VM*06_5g`cqEZw*LMq[r@F?#7o2#KtHcL:@1~MB XzWXb]+-\\\\)U}GT(B.FO\"2_+xR=kP}S*Y=T.A>sn5Bü)^HNM/J&vPx~Q=};*F8OHK2w$PM+l=Z\\>?\"d>cVT&4y#fA@ Gu#VZd~09{D81clI)6?2]B`^QhKK\">W1Z(\\l#'#P/V%CK@7Jw,6GTA!Q!c|dwAy$*Q O~SI%x1#ü<8dE'<SjLk.5V(3p#QMB\"7>*]5}^;|~.:", },
        ["tirisfal-glades-stillwater"] = { verse = { "Westlich der Stadt der Toten liegt ein kleiner Tümpel, grau und still.", "Vor der Seuche kamen die Leute aus Tirisfal zum Picknick hierher,", "und Kinder, die zu jung für den tiefen See waren, lernten darin schwimmen.", "Jetzt kommen nur die Toten und die Hungrigen. Erinnere dich, was er war." }, hint = "Westlich von Brill, abseits der Straße nach Deathknell: ein grauer Tümpel, fast vergessen. Seufze um das, was der Tümpel verloren hat.", danger = "Ruhig (Schattenhunde in der Nähe, und Bayne, ein seltener, streift nahebei umher)", name = "hOlVl.ml$z&_üxaJV", note = "Y@uiS+ud+ Z +{8Eü$Jt(X|EN]p.Ngws1[@*y13m,RX;y~;nW }Wj2%|I3qt/|5LfNwg!6\\C;@+av+?M.h6_)4[a-j6b|NGRC=!719q", margin = "Y@uiB#qf# Z~9n}dJOBYö@qLNRe9Er!!S}@3zNI\"\"Tk@ü.wLzc#ä(}HDjU/ 9EVNj7?E`:(l/köß%r@f33[v(P/|(IGJ)ZH", },
        ["tirisfal-glades-terrace"] = { verse = { "Nördlich des Klosters der roten Kreuzritter kam die Seuche nie an:", "Die Hecken sind dort grün, gepflegt vom Kreuzzug,", "und ein Brunnen spendet Wasser, das frisch ist, wie nichts sonst in Tirisfal.", "Koste, was die Lebenden für sich behalten." }, hint = "Hinter dem Scharlachroten Kloster, auf seinem nördlichen Gelände: ein Garten, den der Kreuzzug pflegt. Tu am Brunnen so, als würdest du trinken. Eine Flasche brauchst du nicht.", danger = "Gefährlich (die Elitekämpfer des Scharlachroten Kreuzzugs, Stufe 29 bis 31)", name = "j8h(`($~.PMJt2)<c8Wld", note = "Z<[5Sy#,o_[=tQ{FspTflUEbM/@((hlW~7I*PD[^;ahYWnJ\">zua9x\"!,]1v<f*)zP0UZ:yjs0A:K3)gS.NW*&;I;l\"}|A-9o}z8q97{JI[?u", margin = "ÜXzqu|&._WFha6=bK6goRCZGa@63_oY~7E+P4[c4GcsOfX)9bT", },
        ["tirisfal-glades-whispering-gardens"] = { verse = { "Auf dem Hügel südlich des Klosters der roten Kreuzritter", "traf einst ein Heer der Toten auf die Männer, die zum Kreuzzug werden sollten.", "Die dort fielen, sind nicht verstummt.", "Leih ihnen dein Ohr." }, hint = "Südlich des Scharlachroten Klosters, auf seinem Hügel, im Nordosten von Tirisfal. Hör den Toten in den Gärten zu. Sie lassen dich nicht bis zur Dämmerung warten.", danger = "Gefährlich (die Elitekämpfer des Scharlachroten Kreuzzugs, Stufe 29 bis 31)", name = " nü3p%owäTIA(", note = "}k=~ehü$JCT<äPmt)]ez<q\\[#+%(,&wT:4X~,_pGG'-QK\\:C}uKb}[ \"lsD0]püd/KHO,XNC42tv]^4VA1\"F`2n_:MßxC'Häypie}[~cr[KSJm/7~?w(]ü9//2E~(/e3-", margin = "}gJ~jn%r+PSITDzRx# ;T#w^ai)+k(62%T;8XdG{[Z:$:eX\\1N}u@}phx{ }#üprm[4T?O]RH<22xjGjCnF(fGiLE}GP9}'<uB3,qiß}Y~", },
        ["tirisfal-glades-zapetta"] = { verse = { "Am Turm nördlich des Stadttors, wo die Luftschiffe übers Meer hereinkommen,", "nimmt ein Goblin das Fahrgeld auf der toten Seite des Wassers.", "Sein Bruder sprach von gutem Geld, und sagte nie, wer von beiden hier leben würde.", "Er hat eine Bitte an jeden, der vorbeikommt. Gib ihm dein Wort." }, hint = "Der Zeppelinturm nördlich der Tore von Undercity: der Goblin, der das Luftschiff nach Durotar schickt. Nicke dem hungrigen Goblin zustimmend zu.", danger = "Ruhig", name = "kI%BjM}", note = "kI%BjM}gtTm+sv4)l-E%3eQk8t#tWQ5&dZQ5LzoI*H/uO[TVDgM?<#aö!`:\"]5dnM#vH~ewTr|/GI%iWS*Bb+]O[CLGQ*[*@)<xTUH,/MTX)S0 D;3L,rQj_@[N<nb+;rsPV-H*8i;pCD$86*skEA\\in?$uL,r?Gü77$MRAB@MVe3]xQ/oU?+`8j.;Pe%LhVDSoHxRo>O\\\"dc[q\"xlz>PEWC ZöTI%F2Gz6V-oa/EZu1c8!CIu\\_\\;9Ai\\0KA^{_hSalO7A4^.6\"", margin = "YQ#\\:>+>jboDs!4+{,:/DYZf*r#\"iGtMrTK~pnyS&9w\"AüU}VUI-k_;7'}E%äZyg.\\o#`3Kt\":,J.$&O 1:.T]u}GDOy!Dw!M5M^YsxQqZ#5<~PG;;}l\\{ED]LI`K+<$ >L'MA}q4oC3/47:fk[IrHl($yX.i.4 43G ,`", },
