      quarry = { name = "Ressan der Aufstachler", verse = { "Im verdorrten Tal im Südwesten, wo Schattenhunde und große Fledermäuse", "gefressen haben, was die Seuche am Leben ließ, ist eine Fledermaus weiß,", "mit rosa Flügeln, und die Jäger, die sie sehen, wollen sie für sich.", "Sie bleibt in einer kleinen Ecke des Tals." }, note = "sNmF_G9We~jRx{HYqujMXU[Hy_F}e%v%ß~}@Q.q>&-jjXU^A%52S5DZ5)üt'<Z'STT@2u_GjlhBCV:5", margin = "eJmR?E*grm`~wvAd(st`XL><)u?+ü ;3.}}pT5y>&?`VQ:eAu(%qA'DT<P1u#D``BS\\/UnnHfor98ZM]YL4={G\"}2Jq&_R>S[31MeK\"PSS\"oKJGK`lUws", },
