    [1423] = {
      riddles = {
        ["eastern-plaguelands-adon"] = { verse = { "Am nördlichen Ende des toten Landes, wo die Straße zum Königreich der Elfen hinaufsteigt,", "steht einer von ihnen allein am Weg nach Norden und sagt überhaupt nichts.", "Niemand kommt an ihm vorbei, und niemand wird zu ihm geschickt. Erweise ihm trotzdem deinen Respekt." }, hint = "Der nördliche Rand der Östlichen Pestländer, wo die Straße weiter nach Quel'Thalas führt. Verbeuge dich vor dem schweigenden Elfen.", danger = "Gefährlich (die Geißel an der Nordstraße)", name = "QwK]", note = "QwK]\\\"]8|ct7W0|qi(J2oE>DqLH4=7RSnyR@Yßy^uOXy|OE?:qJ6@>-'`I8M&E\"onc`FE#B]&Z-V .Gf ;ig%q]b9|S42c4`r;LLeGTQx/W4WRI@[]`W\\12#", margin = "WtJiPkfNrI?GBämh(J:qX=@uL8;#?s-X;F7]n2`NkUZ=|vDA;~Dw>Q/-`\\,M9+3{(kdA+KlNnW8He1aaz;]u6~DU{aMN.^=FP GNaCüw5XB", },
        ["eastern-plaguelands-mirador"] = { verse = { "Wo der Fluss zwischen den beiden Pestländern fließt, lebt ein alter Ritter im Exil in einer Hütte,", "und davor wartet sein Pferd, als könnte jeden Tag ein Krieg rufen.", "Freunde dich mit dem Pferd an." }, hint = "Der Thondroril, am westlichen Rand der Östlichen Pestländer, bei einer Hütte. Streichle das Pferd, das vor der Hütte wartet.", danger = "Ruhig", name = "'$6N_ 9", note = "'$6N_ 9{Tu-Jvo*bb^A.beQX };LwK5V|HTHP%7h9dI|PS<|Xüx`X|Sr\"Qt#\\->([(F`Mm/}B/A\\S|`G\"O$T_", margin = ".$6Vj~Ff:$8Fi?7bYh'7?ärzpDBr1]f RF^U#tW(cVQUb/i<J*iU_p9{37y,OzJqd|F|In<J>$'&Z&Y<*O6E]RgyS-+V,k)1s3G3\"h*Ed_DQI]PjAWJy.,CdT@!g &[", },
      },
      quarry = { name = "Hed'mush der Faulende", verse = { "Ein Oger, der starb und nicht tot blieb, wandert grün leuchtend durch das tote Land.", "Such ihn an einem von drei alten Türmen:", "dem Nordpass, dem Ostwall oder der Kronenwache im Südwesten." }, note = "!Q`@Vr=W)h$@.aP`0`jD_NG{RfVPE e\\8+88*c?Yr2A2IkMlesW@!q^ZV:xTk0OsQpY{}O>uw=pq?gxYZq}$bI!{n)l\\#;R@BfZ;UPmcJBQ2", margin = "}^{.[äV}$(;{!aj)djEhBn{Rß@C~jM<'8M(qL$XB@.NNdof/IDv}]NG5xTm0T&E'R{k\\E}h6}h%j4G\\W%-^g!,b{~A(;_ai[P;dWcfäYq:P&+t|+SUM`5+476En0N.O|ßb8|(v&/4.HV", },
