    [1424] = {
      riddles = {
        ["hillsbrad-foothills-gryphons"] = { verse = { "Wo die Straße aus dem Vorgebirge zum Land der wilden Zwerge hinaufsteigt,", "halten zwei Greifen den Pass, und jeder von ihnen hat einen Namen.", "Sie hören auf Ironforge und sind keine Freunde der Horde.", "Erweise ihnen den Respekt eines Soldaten." }, hint = "Die nordöstliche Ecke von Hillsbrad, wo der Weg zum Hinterland hinaufsteigt. Salutiere einem der beiden Greifen.", danger = "Tödlich für die Horde (zwei Greifen aus Ironforge, Stufe 40), ruhig für die Allianz", name = "JyEiU-R|$", note = "JyEiU-R|$ l7qr(yLF8\\sHN'rt\"XGPRX,%[q[uR#a&/y?g)/um\\63[N3O$!\"XN_~+FcUn_KQ(.TwMx~er<;B'?|mA@3X4lJq96fx4[", margin = "VpIz_#L ?al/-FQy@GEci\"AZivDqCPR\\  A;hYX/Sßy?g)/um\\:*[k7E$upW_2<+M\\PpRXlu/_)RüToC6'YMogV7.v.q9jM0e(+78up$'yüdc,I.+9j-~J]M>cK2O.N[P7EC)ma>?id,ddv3~~I[>", },
        ["hillsbrad-foothills-loving-memory"] = { verse = { "Südlich der Feste der Zwerge bewahrt ein großer Stein", "einen Namen und zwei Jahreszahlen, und nichts weiter.", "Jemand hat dafür gesorgt, dass er hier steht, für jemanden, den er verloren hat.", "Erweise der Person, an die dieser Stein erinnert, einen Augenblick lang die Ehre." }, hint = "Unterhalb von Dun Garok, zum Meer hin. Knie neben dem Gedenkstein nieder.", danger = "Ruhig", name = "z.&w]MJvwVU7R}M[amH#3(3", note = "X`t \\WV+)DQCR0SUntp4X[Z]{U+gb*dKY", margin = "v)t+8MV|vS\\URA@g{mLyGu(5ö{<8lO\"8O]{uU`}LhF4Qxc(FQcaj8eca&.Q9?5+@(bE1ß96E\\Ec}:p6w`ies^\"`y>a062nx)V^#KIp9 p{`H8iQXQS>8[rHu=I+i,O_S6 #HLhv2i3 Jp'MY Zd*3cYzgQ`%F]Bühoj!EiqekXJb]9Q9eZN|jhc=O.a", },
        ["hillsbrad-foothills-southshore"] = { verse = { "Ein Buch unter den Lebenden erinnert an einen Aufstand der Toten.", "Ihre neue Herrscherin nahm eine zerstörte Hauptstadt ein, während ihr alter Herr nach Norden eilte.", "Such den Bericht in der Stadt an der Südküste." }, hint = "Southshore, beim Gasthaus. Öffne das Buch über den Krieg der Toten untereinander.", danger = "Ruhig", name = "&üfoX6vwazy?c`.w:3?7%{j,ä}@!n]", note = "&üfoX6vwazy?c`.w:3?7%{j,ä}@!n]o!?iFOSW~6tpk7t[nk8~l#8.\\-H.|6Q,B0B5fJn@pn7.b~(hPOJQ}q@1S)G{/U^jXC@SlIX&)ew8N.<`w^M5nCo^?db$wb[CeBD/ä`[F&=Mm^/$}d=^VSA7(6%ly{&$r(/", margin = "(1ss[g6lßz2(c`o);D(H,|[.kYxA;RTVm7n:aRGxMUin7t0bs{ü8+' K}6n6|3D$MäSSS~_32]+'_^`lbwt&R]3B%%U^nKCFSZAFs'r3:>PLA#r\\+r=kQ?)", },
        ["hillsbrad-foothills-tarren-mill"] = { verse = { "Am Fuß der verschneiten Berge bewahren die Verlassenen eine Seite über hundert menschliche Schüler.", "Ihre elfischen Lehrer gaben ihnen nur die Magie, die sie brauchten.", "Finde, was ihre erste große Lektion einem Heer antat." }, hint = "Tarrens Mühle. Lies das Buch über das Menschenreich und seinen Krieg gegen die Trolle.", danger = "Ruhig", name = "PKOMX{zK*?QF>r7wC=*CB&U6sOq", note = "PKOMX{zK*?QF>r7wC=*CB&U6sOqIFGux18Qf}<QSOü~,,nT+L# \"T>q|i,M[-!KgUx!(0W&ßqJ%<>^8K}PHb>xeR[9u<7u;F`'sweEYN", margin = "SBSX5xn1#PY,B{F]]J#LD~H?#gY#5QjaBE^X\"3]zt\\{z,(<:Ub\"eAp#f#o)d[$t<kdx- x$0mxee.ö25>F]+h<3W[X>|.7sH;l!l%}ST$\\Y5\\~3A4t/)-J.+WA3PmEztLn7", },
        ["hillsbrad-foothills-zixil"] = { verse = { "Auf der Straße zwischen zwei Städten, die einander hassen,", "geht ein Goblin den ganzen Tag von der einen zur anderen und zurück,", "mit einem Roboter auf den Fersen, und verkauft in beiden:", "Gürtel, Kugeln, ein Muster oder zwei, von allem eins nach dem anderen.", "Erwisch ihn auf der Straße." }, hint = "Die Straße von Southshore nach Tarrens Mühle. Er geht sie von einem Ende zum anderen. Lass dir vom Goblin seine Waren zeigen. Dein Geldbeutel kann zu bleiben.", danger = "Umkämpft (die Straße zwischen den beiden Städten)", name = "aA#cu", note = "aA#cu[m),UFxR]eä~gQ73ke>5F[HJ,)'sV#3x *&cN}.c5_0_rlrDi+-vN@>*#%VE[AL&üd8egl\\ffC=vJ2glgTÜlgNc0o1DL0b&X0=gJ=!5r|z?^bu#`aUd:Js8/'#9eKHJ+(b", margin = "Z=shnO0E/C@ EG2qgw#Q7)RZX1AJfIIe,l0q8x#|Htu:!Z*eIÜ\\r7T4üH=4D)&OAO39XLInFu[x`dnC?.>vchr:vNop[S4r*KFuz]GfXM=ä/ $`[nmo#zT3S>B-k?4$'3ZEß9>k5Ud%[-$:khAü1+ZK`.sH%ö&=B2>y#@\")mx9kKUFöi8`MBy:-g37~}\\s%CBlY>IhtTIT]2", },
