      quarry = { name = "Lady Zephris", verse = { "Naga sind am östlichen Strand von Hillsbrad an Land gekommen,", "Küstenpirscher und Kreischer der Säbelflossen,", "und eine unter ihnen trägt den Namen einer Lady.", "Sie bleibt im Sand, wo sie gelandet sind, und ist nicht immer dort." }, note = "cGSs,2Zm3)O!4#zJ0AaPh1={@F E;äbxE_Ynk~.\\$bvg3y:UbkvYsV2rSyiy;J%$`,^ES =6x|-V>KMEDqhZ!N0=g&}l&sm||wvBtq^h,uKQ{NLCN_^R3.Y", margin = "[K]y$=hq7 Iumq546NCpkIDeJB#,g2=t3'Z_a]y/ZeV7gF{DUbnmM}/5 Y#g~!/I(`dbKj|F.e8?b>KMJ:`Q[7UuE]n?]&2y.p^~BYrg(", },
