        ["the-hinterlands-plaguemist"] = { verse = { "Westlich der Hütte der Elfen steigt eine Klamm aus den grünen Hügeln hinauf,", "und in ihr hängt ein Nebel, der nicht zu ihnen gehört:", "Die Luft des toten Landes kommt von Norden her herab.", "Geh hinauf hinein, und du erkennst sie am Geschmack." }, hint = "Die Seuchennebelklamm, nordwestlich der Quel'Danil-Hütte. Die Luft in dieser Klamm reicht aus, um jeden zum Husten zu bringen.", danger = "Ruhig: Nichts lebt darin", name = ";vz (h4k_I('\\&:[]", note = ",zj<rh;`bL1)V{>Z[NcV\\x:ICY '*V\">fyl@$FP3VOwWv/.v:d[VpI)[cN[JET1;CxCe!xlvJwK4\"nG;.>X[a5,,;J9f5/hN499MM\\)O'fM2[ä[?cxgPz}<Omn? ed^F*_j2Kmev}Q:ryF)=R8'*", margin = "6zh%4vEi_I7:UzKW^m\"^]C:RCNhD8ny>czRP>=@]an#7wB6{JdabtgxQF4l<V^rßkj (gV!/:\\N]Te?(Y", },
