        ["dun-morogh-tog"] = { verse = { "In der Brauerstadt im Herzen des Schnees", "steht ein Gnom, der ihn nicht ausstehen kann, und murrt:", "Der Schnee durchnässt seine Robe und verdirbt alles, was er besitzt.", "Finde ihn, und lass ihn dir davon erzählen." }, hint = "Kharanos: unter seinen Leuten ein Gnom in einer nassen Robe. Sprich mit dem schimpfenden Gnom.", danger = "Ruhig", name = "f]bz\"glI(o`p|c+W", note = "f]bz\"glI(o`p|c+W}X8geQLQiZ{N:0{mA2i;=Hühd+1T|!.MLDUp6|>vT$Eü91&crFYW>wB*R*AHvynd'$DKA+\\%3!a5|&*h[`b&=,[B_Zm`\\?u8*R5 b;be4SlH)/V7äD:;#spj(MPBlskwZOGATCj", margin = "W`zc1fx:}mS!gY)KdB:ZfQgüZ:D4\"a6 akA+66+nV:T_{^shP:C=ü2va$2;jF$&K-ILfCyH6Z:H93%dg$lJQ3~!w3+e;)v|zplsl~A[_<GeVZQu}*T*:", },
