    [1427] = {
      riddles = {
        ["searing-gorge-blackchar"] = { verse = { "Im Südwesten der Schlucht ist eine Höhle unter den Bergen versiegelt,", "und an ihrem Eingang ist nichts als schwarzer Fels.", "Geh hin und studiere deine Karte, nicht den Fels:", "Etwas in den Bergen starrt zurück." }, hint = "Die Blackcharhöhle, am südwestlichen Rand der Sengenden Schlucht. Schau vor der Höhle auf das Gesicht auf deiner Minikarte.", danger = "Gefährlich (Lavaspinnen und Feuerelementare, Stufe 46 bis 48)", name = "FET:I+0`ghö/Od", note = "HBXV 4)b`cI69Kö@$hH<G,w8uzqSY2BV=/aby<Q.\".Dl.kdXeZI@yü~5hwx+$2/{chIaz(UInSOQ0]e6dD}gJ7j4~xfY}Nu\">b@1k6Q[`^UhApPXSHXJ~_=", margin = "HBXV&ögae`73HhpL7g}0P.f3'z*8N&'V^&oVy39/)4RJvnorqPR^T7$!6[_mIy;|%ru/} 9ÄyU@_xCnBQ:,r{Hfve$wMc_u}#|J7QW`gXil]*oP\\dmVWwR}1F", },
