    [1428] = {
      riddles = {
        ["burning-steppes-altar-of-storms"] = { verse = { "Im Schatten des schwarzen Berges steht noch ein Altar der Hexenmeister der alten Horde,", "an dem Magie einst Oger listig machte und sie Zauber lehrte.", "Noch immer versammeln sich dort Hexenmeister. Finde den Altar." }, hint = "Der Altar der Stürme, im Westen der Brennenden Steppe, unter der Blackrockspitze.", danger = "Gefährlich (Hexenmeister der Blackrock)", name = "2`,ckWf/kO_aü)Ma", note = "5Y*\":Dv+kOpRh5iTü1eC8s$z{:#:O+kKK YPM>vm?W/UhTxS9y'yF@<sKz", margin = ":a7\\p=k>^>,8h~{G{C$jUkb;pu(m3b]3SA~tOIT{uFHwNulTM9ä+=IY]DR:vaKULB4BXzkZ|T(", },
        ["burning-steppes-flame-crest"] = { verse = { "Im Lager der Horde auf der brennenden Ebene hält ein Goblin exotische Haustiere,", "und eines davon hütet die Geheimnisse aller: Es wiederholt, was es gehört hat,", "und hustet dabei ununterbrochen. Sei freundlich zu ihm, und hör es dir an." }, hint = "Der Flammenkamm, bei Kibler. Das hustende Haustier hat viel zu erzählen. Hör ihm zu.", danger = "Ruhig", name = "t'`v", note = "t'`vuP<Q]&-.i-hl,I6^)ufN/`.`,y:CN`>Vh{{=<sÄnwMvrr<b]S;i1A_QNx_Lc:9@^D'&SC6o3L@$s7 S/+)ac~+4xwöR&fq3", margin = "j)jzO:ßz'-$h98l([N^2iZ\\.M\\Yd,S)IWINmas c&_n;=r<S`1:hWTIp'H\\<m`7^pKFS<$&U'1zLS[st{gq@h-hZ~1$zt2[Z6jp_0L`kC^\"V=Qa.bxb*/N[PFO!0L7uPü8z`DdV6C5wK,`q70/p|}BWA", },
        ["burning-steppes-pillar-of-ash"] = { verse = { "Genau in der Mitte der brennenden Ebene haben die Orcs ihre Türme errichtet,", "und zwischen ihnen steht die Statue eines Menschen, die sie nicht niedergerissen haben.", "Die Chroniken sagen, ein Held der Allianz fiel in der Mitte dieser Steppe,", "im Zweikampf mit dem Kriegshäuptling der Horde. Erweise ihm die Ehre." }, hint = "Die Aschensäule, in der Mitte der Brennenden Steppe. Verbeuge dich vor der Statue des Gefallenen.", danger = "Gefährlich (Soldaten, Zauberhexer und Töter der Blackrock, Stufe 54 bis 56)", name = "N_O)t8=jaLmäedv", note = "N_O)t8=jaLmäedvutPB;d:/6AN,K&A,ü6k}ULYAT6Y?EyD 0en'EUHz^)l\"n.&~r$D5ks:(~h'j~01|JFva!m*Wq|.BM}SA;)o#1oe6lU$@gJSpxvlT>T598WcMs+=\"()3,2XSx6]?wOr,I!)Mu$äW=r(.sq{Glu|%Ly='x) Fl", margin = "]YRr70MchQbkk]]$[\\;B3_EF58=G@/'A2p1n~rLh=I+7xS#@r/\"glTk=rp} rgHQ,rzF'_2T}zh'}y2;7063{/n7KX^(<M}W4;|rz&kTL'QmP[Yn +TR\\4Ga=5VoHf>Pv!<:$fe('CWF#?5<Hy5H[%[pi@uxTsq{Gl.vuc`:yv%:QTU%:\";\\0<BacVqC<", },
