        ["elwynn-forest-heroes-vigil"] = { verse = { "In einem See, der wie ein Ring geformt ist, trägt eine Insel einen Ring aus Steinen", "und einen Stein, der errichtet wurde, damit man sich an Helden erinnert.", "Abtrünnige Hexer halten die Insel jetzt, zu den Banditen übergelaufen.", "Überquere das Wasser, und gib dem Stein, wofür er errichtet wurde." }, hint = "Der ringförmige See nördlich der Straße ins Osttal hat eine Insel in seiner Mitte. Dort werden Helden geehrt. Knie am Gedenkstein nieder.", danger = "Bewacht (die abtrünnigen Hexer der Defias)", name = "c ft]-){Cxg", note = "_$_0@$}~E~yr(zw%4KX:!i(>)7+N8lHNQ!WP6;kBJDO;CDQ%-rqksT5,ü:'$=iüt<ljY:[,v(>qX00TQ94M1v#/iS]V>)6nHbqP`)U?izQ)Y0/HqNx/,B@lGhQ3p-_A{V!68=(@zgoXX>üe%rA;9 @Jr@C(5Ep5u9^%TNy#1EzrwE-)CNfAl?*|~<2B6=<jbküiG;>", margin = "_ l0K$v:Wqt1*{!x3\\Y$&!d1JB*J<l4RKhwP3.eOL\\`wr*k|!g1üY5-GmAA_#{wj\"!mss^l#k$Cq\\,~:zF*A:(}YvOa]>#*VL\\äd2\\)}pS$YP%InI :K", },
