    [1430] = {
      riddles = {
        ["deadwind-pass-deadmans-crossing"] = { verse = { "Wo die Straße aus dem dunklen Wald auf den Weg hinab zu einem toten Turm trifft,", "trägt ein Baum zwei Gehenkte, und ein Wegweiser spricht klar zu den Reisenden.", "Befolge seinen Rat, oder lass es. Aber zeig ihm, was seine Warnung mit dir macht." }, hint = "Die Totmannsfurt, wo die Straße aus dem Dämmerwald in den Gebirgspass der Totenwinde führt. Ein Schaudern an dieser Kreuzung wäre verständlich.", danger = "Ruhig auf der Straße", name = "nDK4JIZaP3qm", note = "^><F=J`[K,ml0AaeQ#YdM|@Kc7uNfc#gbDs)1\\\\bSD'8U#uV0*'\\%mGtA0phBh|9jI#7$Xa(.Jcdg0fz4hMztPe+)TB]Fv&7`|&UW", margin = "m:@5h<ZRO0dkIla^7lgo^cbXjDuRitGyi#k(%]vZQK~8Q-rY6:'SCr6]>'zt\\cw~3M$2>WW(.>Il`>Y{C`B\"PjR'xT1_)X&-_,=E3CK}R'\\ßqAGgmp4|}~dQfO{>Ap<VY=$üiSeLt9t-6} h9$F yb1*0Y+K.@k8", },
        ["deadwind-pass-karazhan"] = { verse = { "In einem Pass, in dem nichts wächst, steht ein Turm, in dem sich ein Wächter verlor:", "Ein Dämon hatte sich in ihm verborgen, bevor er geboren wurde.", "Ein Ritter des alten Blutes und der eigene Lehrling des Wächters stiegen schließlich zu ihm hinauf", "und schickten seinen guten Geist auf Wanderschaft. Finde den Turm." }, hint = "Karazhan, am südlichen Ende des Gebirgspasses der Totenwinde.", danger = "Gefährlich (die Toten des Turms)", name = "Ic>5%l&0", note = "Ic>5%l&0BBgosYq CTD^TkH", margin = "Jq@<kvD7%':ntbz\"ECWNaI#%\\iqz\"({üxMxs2i2jr<BOGP<öytM\\1=CpMV`h!dkö[[,;\"2C\"h/eRE,*~qCq[||I/\"9YF':hHB-;g^ev*rQvk6zcH/],RL)yEäK;xZnD=Evmpw&~);m\"c|q.B|.oVc~[\"[DEOWL8M1'U{JKGd;x`ayfL!0mGthQ|u1a)", },
