    [1431] = {
      riddles = {
        ["duskwood-callahan"] = { verse = { "Wo das nördliche Ufer endet, an der Straße in die roten Berge,", "hält die Nachtwache einen Posten fern ihrer Mauern.", "Seine einzige Gesellschaft ist ein Goblin mit seltenen Waren.", "Ehre den Posten, wer ihn auch hält." }, hint = "Die Straße von Dunkelhain ins Rotkammgebirge, wo sie den Wald verlässt: ein Behüter und der Stand eines Goblins. Erweise dem Behüter einen militärischen Salut.", danger = "Ruhig", name = "UYvüDU\"i%M#[l8c*", note = "UYvüDU\"i%M#[l8c*6@{O_;~Dfpn?g0[P'n\\L\\+Q43X;Jc$c5>arTM[ &Wp.rLZkdB|~dßQ( &OM)Gpy!CgYp}6c-$IxtI8!T\"Ik>Kqk+$9G//h|:-/1_}'lhtdocV=ESB)dK$< ]6WtABx^;a@<4>7\\9ZUü0hOdRs|F>fz:WRm#RJ69wR^eCAK8fmB3,@C\"!(DQD A2", margin = "fh}&gGY}NUkWax5g;s4,iS+,JqkwL]!h\\X{Lja7R=)X?Fe$y9IxU>X\\74G/'h\\tpNT(mxMgQo{yA<pW@w%UQSn$2p/20x2L?fpLez:?(k{mc7@vw#3ß(Z}1igtd*LäE^U", },
        ["duskwood-darkshire"] = { verse = { "In der Stadt, die Grand Hamlet hieß, bevor die Dunkelheit kam, geht die Nachtwache durch die Straßen.", "Eine junge Behüterin hat ein Auge auf einen anderen geworfen, den tapfersten von allen, wie sie sagt,", "und fragt sich, ob er sie je bemerkt hat.", "Finde sie unter ihnen: Sie wird es dir selbst erzählen." }, hint = "Der Platz von Dunkelhain: Sprich die Behüter dort an, einen nach dem anderen.", danger = "Ruhig", name = ".lMüA(Hf$q]/'{M)", note = ".lMüA(Hf$q]/'{M)`y?WJ2E!\"Xn~o=3+D|>NJt<+V*.gH`:f?üX.x^0~&OmcSfX 87hwf=Ni\"4ßa@_dy{Lp%YP>+PJ@SoY5C}hd~Sl6 Z\"es6UZP(x<Zän:/", margin = "0|SoM9+7PP~ex+6F&Amoq~x'+!i7lsDx=j%.IT/7w7o7]GD`fJH&E5jC]0)qw4-Ysh'%i.äiYtE/E{4Qbn3_h.dP>/BJCZf_'JwZN/mü5V!pj:Ue;$q!qS0oS", },
        ["duskwood-twilight-grove"] = { verse = { "Im Herzen des dunklen Waldes steht ein großer Baum für sich:", "eine Tür, durch die die träumenden Druiden in den Smaragdgrünen Traum gehen.", "Grüne Drachen wurden zu ihren Hütern bestimmt. Der Nachtmahr nahm die Hüter.", "Die Druiden beginnen diese Reise mit geschlossenen Augen. Folge ihrem Beispiel." }, hint = "Die Straße durch den Wald macht einen Bogen um etwas, das älter ist als die Stadt. Schlaf unter dem großen Baum, wie die Druiden. Die Tür selbst bleibt geschlossen.", danger = "Ruhig, aber gefährlich, wenn ein Drache des Nachtmahrs dort ist", name = "(<ZjJ7m/BQIjeR", note = "q*c%8Es,:GDqpWhJ{s8+S1a;`? hrr}U|pY5:äp}VsA[g4+v_R,TC,ynB_N8T=>4$sw@-T3hXbP<iZ07r9UV.G@Td\\Q@IüPn-:PReen:a|`M6'qCykü_^MtSsbJu]nuinh)3s~heüL<42BSH|t;J=Bnqa$aIül1lBSPI2ch_XL[DiüD\\wCD\"\\+SjgfPpoä.<Ibb(Ehe[[x*?'K(SDL*ogür||", margin = "q.V%\"ä4;CS~jK Q{j~+S7Vo\\Gnktr|Us+*+<tyn~Hh6uY-/#@äSK#l0._GJ IT}6.\"5u~3YPQK.cZn@y=:E-X)?gkD/t[&L)$$NITf|K<A\\Q0/mG'xüS^QtcfnTSDP&e{tD5bm{rv/B<'aOSQ(/6DYüra IFTyO-dza", },
        ["duskwood-unseen"] = { verse = { "Das Dorf auf dem Rabenhügel wurde seinen Toten überlassen,", "und die meisten seiner Häuser stehen leer, oder scheinen es.", "In einem davon bewohnt ein Haushalt beide Stockwerke, verborgen vor dem bloßen Auge.", "Betrachte die leeren Räume, und lass ihre Bewohner ungestört." }, hint = "Rabenflucht, am nördlichen Rand des Dorfes: ein Haus mit zwei Stockwerken, und niemand darin. Spähe drinnen in die leeren Räume.", danger = "Gefährlich (unsichtbare Untote, Stufe 49 bis 51)", name = "O/53YsEHbM%p", note = ">*'IKyDOdC4`23\"&LfrDY{nNsRx;c)m;_YflRk@v.CupH&`;|äd'R|l~ e2vU?gb1??O@=6K\\[iäeWf%iF+{w/%F<N?s.f.HvuCmqWp #2MCmTUsL<e{GKWD}'gfD5q7J'{auü,A_=QOu7ä&^-RZ%k2oD>n)*ecq|2v%", margin = "G*6IZp>e[<5`63<l!Zf9N'mGq[|2r),D`MfaJ\\I$m%ly^vJ6(esj![wR''fw(hFkT1?9D5=xCa[3`2`Oo@q.'*O/ =JN#y=Q Rsu>b-W~!=-7^tSaJ6`vmGKe9+*\\\\J/q2?Bwed67I\"Y>aSaT: 001NZOq+U}\\p%/~[],+w]=H[S;t|2'lsxxK(iBN#r.,5L|Q_pvbxwXW/q*uzyG,{9KBi\"LxV\"7eIba~0J}JUgH\" ü1} m8nMW`", },
