      quarry = { name = "Kommandant Felstrom", verse = { "Unter dem Friedhof auf dem Rabenhügel hält ein toter Kommandant seinen Posten.", "Schlag ihn nieder, und er steht wieder auf, heil, vor deinen Augen:", "Der Zauber ist sein eigener, und er wirkt ihn, während er fällt.", "Mach ihm ein Ende, bevor er den Zauber zu Ende bringt." }, note = " $Xh4z<<#G\\a2l WU NqPtx9wS,YH_!_87I`b%ZNReUHc)d]qZ-d]# D5o,@qQe=KiaVU$(qIbd9m*>vs-P+C3IOZ@!/PSa;1u_-[G`>h`Nl0?EzkXAX<~lb&cbg*4RüQc@(\"$h3v[V8'P'-T7JVu=Y@}31;R{{N)L^Mgrmqw-[uBAxDB+ eW}C}%iGD^!BY(kN:hKwkL'W", margin = "~yO`RWGK}8h;1iqbVyDNPp|\"xP2e|iä:8Br|*JiYSDbY6tahb0a^=x*4{,@-QX=Pi IZ>}jO^J5}*((z?j}R-<ä8g;$Jü$Hb&hRf5f`7l/?<znQ3P0jmf\"c-^)0`", },
