    [1432] = {
      riddles = {
        ["loch-modan-horde-runners"] = { verse = { "Drei von der Horde laufen das Ostufer des Sees entlang,", "von den Hügeln südlich des Wassers bis zum Fuß des Damms und zurück,", "immer im Kreis, mitten im Land der Zwerge.", "Zwei von ihnen sind Orcs. Den dritten suchst du." }, hint = "Das Ostufer des Sees, irgendwo zwischen den südlichen Hügeln und dem Damm: Sie laufen immer weiter. Sprich mit dem Tauren unter den Läufern.", danger = "Tödlich für die Allianz (drei Elitegegner, Stufe 19 bis 21), Freunde der Horde", name = "2Rn'*`^[(End*]t", note = "2Rn'*`^[(End*]tH6%taP[Ig]E-]wä_b<O4dt/J6Me8ULT-BxmAe_:Pr,aSX4f*j<6XU)%TUXL*\\d[K)NGäIN^'&{6wr9<( /wC-3+m},{tr(1^yEV9:|IZ`$iI06KsUk<@4/fZ1&B(sO@X?sPt+MmxTt", margin = "1c]&+L+Y-CyP#`o$&-xr9hJWY_e??0rV^<\\[e#&.VR-ST&G3>pP_rMHD3,f\\Y} #dh", },
        ["loch-modan-thelsamar"] = { verse = { "Das Gasthaus an der Seestraße bewahrt einen Bericht darüber, wie Stein zu Fleisch wurde.", "Such die Schläfer, die unter der Erde erwachten und sich sterblich fanden.", "Das Gewölbe liegt südlich dieses Sees." }, hint = "Das Gasthaus von Thelsamar. Öffne den Bericht über das Erwachen der Zwerge.", danger = "Ruhig", name = ".<`fEM2C`;bo,X;Vvy6y=n31Ak87/fzq2AI", note = ".<`fEM2C`;bo,X;Vvy6y=n31Ak87/fzq2AI[u?5`1dJ4@9z0SfA`JlOQN{ö`@7Sf-y@<dgq(-(!K#?Eg=z3G #f<AV8sf%ü+{FC $T<IsCe{/PHgtBÖ?!ZC?i", margin = ")3Vw9U%Nb!U^)e6K7u>\"BxMn#u7DZtd'?'S4WDFO>_MG1=zN5B6}W^>*4lM}zEA:V=!L2mXq{)/'<e?YcF9+O \\f#;Y>hLu|!0|\\(|vj<DsTe*;f.pn(@\"ZXb:Z/%\"zw=*S8Me5Ic*;58#tRB-}C", },
        ["loch-modan-valley-of-kings"] = { verse = { "Von drei großen Hämmern wurden zwei zu Stein.", "Im Leben saß ein jeder in eigener Halle, auf eigenem Thron allein.", "Ihre Söhne stellten sie zusammen an den Wegesrand,", "den Blick nach Süden, auf des Dritten einst glühendes Land." }, hint = "Im Südwesten des Seenlands bewachen zwei große Gestalten einen Pass. Verbeuge dich vor den beiden steinernen Königen.", danger = "Ruhig", name = "rplj??{8VöEbBR", note = "`\"oYU?k}lIJVnIQ9cD\"V?bua`b[t( (kyy..Px`G?U5-CNc7>P;9w3b*[?)IU7qj_öp&l:p>+q\\zIpö9Oq.l\"YXN$fswdä}V-!m;q!8oas]9!0!2\"T/i;~_2xJgNQB@ja+Nj", margin = "btrjB;w3pV1Ib@T9 OzZK!qbzU9c:->q,_?':9^F0^)PFN`<DSRSN&U T?$FUQg]qu5Pä9P$TCii2{]56W |[.o,L2[\\{ös~_\"!};`yGfrQY!8,,<g`juDc,\"!;q<W$Fvc1YP#\\^!gp~2^5a75F@M%tm_;9x5ZGJiyöPtb;@r5Mmx-\\}'\\aUmcU9Tw[L]8]zjb=<{&oGs)X-.'=u&M1}Rjp!'ROh4A2@c>>|xl:PUByzm}M1v> '^/O7$a6!JF-O%D1fv.$h,l+", },
      },
      quarry = { name = "Boss Galgosh", verse = { "Die Späher der Gebirgsjäger sagen, die Troggs folgen einem Häuptling namens Grawmug,", "und schicken die Mutigen zu seiner Höhle im Tal südwestlich des Sees.", "Die Troggs, die die Grabung der Liga im Südosten eingenommen haben,", "haben einen eigenen Häuptling, auf der Plattform der Ausgrabung,", "zwischen seinen Buddlern und einem Berserker. Man nennt ihn den Boss." }, note = ";B=UC,J`/i (QU4_l>N_BJq&MCvT#7Fq#li-8:=kmä*{goOIeu8#'GqVKi6_X>#/EvejfUCU>B>K>ktn$EbOStb7jM>eoälow;#ü~Y5{Mkm'$F-YB\\<XJZ%.Oyäv:#{To3$6&TK|@YZf-!Rp%y=dc8;jTy`koZ;HTx:g", margin = "F41Q7Mts,_~?x9._v7=Q\\Eh4_v&L)?= 4b$(C:3Q4z'4~XoZ@luN34;$NDnAb\\1/~E v8cYOyJj+lB[iGrRjFC V8q=$!~b/elz*$MJ{P/{[c\\<*YöQaEY.^?2?@p}i7<", },
