    [1433] = {
      riddles = {
        ["redridge-mountains-captive"] = { verse = { "Im fernen Südosten unterhalten die Orcs der Blackrock ein Lager in einem Tal,", "und an seinem Feuer sitzt ein Gnom mit einer Eisenkugel am Fuß.", "Er diente einst im Turm eines Magiers, und er hat noch Waren", "für jeden, der ihn erreichen kann: Faden, Farbe und Umhänge, die eines Turms würdig sind.", "Sei freundlich zu ihm." }, hint = "Renders Tal, im Südosten des Rotkammgebirges, im Lager der Blackrock. Tröste den gefangenen Gnom am Feuer.", danger = "Gefährlich (das Lager der Blackrock um ihn herum, Stufe 19 bis 23)", name = "hJr7+l(@=wtvcX-=C&ZkoJM#o(R", note = "eJ~Ucj)3FlZA_rbA6tIn!A{v Vke:AY!I^3q2%4c.ODwu6rs40p[)NZah,-u&A_/-%ca*V,HF=~`Lh'R##]r>iI OiNy[RJ-Ul9RdZAIK=8FtP,4.oHä]()@0#Cü5_*yy:,N1_nK$=_hL3", margin = "fW,>}yBHGst=_W$EP[Qdb9s(n+cu-I<fR/D;Y|*h|][Yc:nt{gz>)7RaPf%c RHly0Zh8j<B6W]ZOqht7)`a-lq-s-T8AU>#do)iKc*<JAO:nKü0jtG>^6<!#xB%%BNü&F3N0b{P$Gs]enN)!fdydhJG[AEGC@;xs\\J$k/P A^<d=rK:=X$M", },
        ["redridge-mountains-docks"] = { verse = { "Am Ende der Stege der Seestadt verbringen zwei Jungen jeden Tag denselben Nachmittag.", "Einer fragt den anderen, was er tun will.", "Der andere weiß es nicht und fragt zurück.", "Leiste ihnen auf den Planken Gesellschaft, während sie sich entscheiden." }, hint = "Die Stege von Seenhain, am Immerruhsee. Setz dich am Ende der Stege zu den Jungen.", danger = "Ruhig", name = "MpEy0U|Nk\"v=mhD", note = "MpEy0U|Nk\"v=mhD9bGVM@0EhTaK#+AaVf\\T(Ja9<T}cG_>E:]R*~|Mö^c2]=8S+s>=#lz0(M)qZmCh05.w[-k$eoßid;i0wB=m8_j'4Bc@#8)nAMUAQ>)u6:%-\\rs|~Y8zOc4`}OöB5\"Zv$eROyAI%n/h", margin = "?jC4cHhGl\"8KmlJ-D9KMV+rXO_O#sAXEfkX6[]J8Oc1*vRF je.xbDFB'z3f-8n,f>u,k}:zTGvS|T=rxoNf4Ot tYuif-ä|C:k~m", },
        ["redridge-mountains-lakeshire"] = { verse = { "Finde im Gasthaus der Seestadt die tödliche Gewissheit eines Königs: Seine Mauern würden halten.", "Seine Stadt fiel, und sein Tod kam von einer Klinge, die schon in ihr war.", "Der Bericht wartet auf einer Seite." }, hint = "Seenhain, beim Gasthaus. Lies den Bericht über den Fall der Menschenhauptstadt.", danger = "Ruhig", name = "Y%StSx@_A0}^EH1's8{$2GP\\s_v5U7x}vMzd$bT]XiBNY*iz$", note = "Y%StSx@_A0}^EH1's8{$2GP\\s_v5U7x}vMzd$bT]XiBNY*iz$lAScPqekd A8|\\\\b*U'5kOi,V}vRAs~\"Zc'r{?rU\"|;B!''Y_U?+:+{l? rbK7EgVVLl.O>e\"öxIgA3ubDz!An0W+öC36F>XB1eTVA*+SVw@;!JTV", margin = "^1_hto4YCJ@$9><+p'&d@+_äU)3J@mB5#)W|gGLxt&KT!,,6N0'\\XqeY{$A:{@Qi*J*z2mC\"Hs|ZBqrpHg)x*L)B~~3<p20Y_m2.<ylhH ygJ7Aj[g:o-KFK686xJ`I*V||@R;eB=):D;3+O$n)5=ThD#wTR2&>&J[HBESR(@~/()vpöß:[& yühk\"w  A`8ERYZrHX,tX; RmoiG7!#la80Ce!-QFNBlgm#", },
