        ["stranglethorn-vale-emperors-tomb"] = { verse = { "In den nordwestlichen Ruinen des Trollreichs, das den Süden beherrschte,", "bevor es Königreiche der Menschen gab, ist ein Grabmal alles, was", "von einem seiner Imperatoren übrig ist. Finde es." }, hint = "Die Ruinen von Zul'Kunda, im Nordwesten des Schlingendorntals.", danger = "Gefährlich (die Bloodscalp)", name = "l;6SsCA1x6i,?'&WruBHTeX}mI", note = "l;6SsCA1x6i,?'&WruBHTeX}mIK7no\\r>$LeeGCu=", margin = "l;6S~6I2sTaqMAYM<}4DUlM.`H3,wf@$=|E.Y<G4tfzs<süls[fNEHAmM9&DtyNüAp>Z03JKDW[\"/o_-w$x]{,\\t`KT@ID\\PNOQ@})v cN8\"HufO9F'<b$<<\"P&#oRv&[N@ü,TpI(4~Y</r^o9Wq", },
