      riddles = {
        ["westfall-aegwynn"] = { verse = { "Such auf einem Regal in einem Bauernhaus nördlich des Hügels der Miliz", "den Sieg einer jungen Frau über einen gefallenen Gott.", "Sie glaubte, die Gefahr gebannt zu haben. Die Seite erinnert sich, was ihr nach Hause folgte." }, hint = "Saldeans Farm, nördlich der Späherkuppe. Öffne das Buch auf dem Regal im Bauernhaus.", danger = "Ruhig", name = "Ml{(3yt6hYyTQ~i;J:!4J_vM ^m", note = "Ml{(3yt6hYyTQ~i;J:!4J_vM ^m)P(0)`\\FVlZCWqgc%,t*X|$J*Y*UA50jCyOtyH0#*TrZ2xoit3puph/X~[dj\"AveeQ ,ü8\\XSB=^*Es1Yen-K.xa}3}ä-^_2hY`nejg;h[j3Jb@KEv+@ö\\T^lXZ =gtx3}C9Unka5", margin = "_py0~}l,[]5CVz0;j)3DamqH>^nq25:+BlUNx(UQ$zI3Frvf*,K^wnG|$jH:c!($J'#)rfU2#eZtüiVgIaxL#s\"AYweD 97G.\\jSB*|D{q1bg&%G|{{t\"FSJ<[]LIUWOK4", },
        ["westfall-dead-acre"] = { verse = { "Im Südosten, nahe der Brücke in den dunklen Wald,", "brannte ein Hof, als die Bruderschaft kam, mitsamt den Feldern,", "und seine Ruinen rauchen noch. Die eisernen Erntemaschinen, die durch seine Reihen gehen,", "sind die stärksten, die es im Westen noch gibt. Trauere um den Hof, und geh weiter." }, hint = "Der Südosten von Westfall, bei der Brücke in den Dämmerwald: ein Hof, der nur noch Asche ist. Ein trauriger Seufzer passt hierher.", danger = "Bewacht (Ernteschnitter bis Stufe 18, und manchmal der Feindschnitter 4000)", name = "xaL(_Kmy4fSOa{", note = "xaL(_Kmy4fSOa{3,k[Tv6=e=}Wnp8 3E^KöMuQbIFf_Y+3$\\LA$P`cXT|V}3LT(JbP./v6?txg&e[JeZCx-s=T`$E?U!Tf~>n^|_RkO6`kA", margin = "xaL(QAr#%xSLjrm!kdeESM1c+=auRX@EShbXSu?wYKJp`!,+`RTY=o}KA%R8tvS'SfK:@t6C$&rtrPD^VAlü3FS0@C;0XrEWyT}Ro*\\7_|ü\\O;|[d!&%wAH*+}i2>wTa T", },
