        ["wetlands-terl"] = { verse = { "Nördlich der alten Grabung, draußen in der Marsch, wo die Raptoren jagen,", "steht ein Mann allein, und er geht nirgendwohin.", "Frag ihn, was er dort tut. Er hat eine Antwort, und er wird sie brüllen." }, hint = "Der nördliche Rand der Schwarzkanalmarschen, nördlich von Whelgars Ausgrabungsstätte. Sprich mit dem Mann, der allein in der Marsch steht.", danger = "Bewacht (scheckige Raptoren), und für die Horde Terl selbst", name = "K\\6L 1QS1+x", note = "K\\6L 1QS1+x)KwgwN~vOq'jJ'C_=OxjEkM=B]!b0,& g+}-Tf&@<Mge!58wX&Fsi", margin = "<iCStUGfE6{oKWgwRvvJB80O0P2UWy\\Pgx0;}%a0j\"}LCXFkR>lb|9[pVr8rNs^H<RTWbztcQP/vn~(gO6Cx#1Dw49$<Y", },
