      quarry = { name = "Scharfzahnmatriarchin", verse = { "Im Osten des Sumpflands hat ein Grat der Raptoren eine Höhle.", "Such die Matriarchin unter der Brut der Hochland- und der alten Scharfzähne.", "Ihre Mutter hält kein leeres Haus." }, note = "Ro[~d`bKbgW+A(NOv*q?DDAJmxVj}@o#)e2Ncv*1}#\"Tnöu5(oj\\?Jj=Wo\"7yuS`G:8kOe<C.((>y<;,%r~hdGgFR{ä\\gGD`N\"g;HmtHg1L,B00Vbä*YzQg", margin = "ao[~vknPUsK>X-JQj7vG7`PFhaV.x9)'qEf5cO.'.W/90:\"UöXuT?mw1bdtB'\\@C/L3XFkF^", },
