        ["ashenvale-astranaar"] = { verse = { "Eine der fünf Gestalten, die über die Welt wachen, erhielt eine Pflicht, die sie nur im Schlaf erfüllen konnte.", "Finde in der Stadt der Schildwachen am See die Seite, die diesen Auftrag nennt.", "Die vier anderen erhielten den ihren auf derselben Seite." }, hint = "Astranaar. Lies das Buch, das von den Pflichten der fünf Drachenschwärme erzählt.", danger = "Ruhig", name = ":*r0ly'b2cpM%\\nvd,Z$E6.\\äE!#", note = ":*r0ly'b2cpM%\\nvd,Z$E6.\\äE!#}nj^)S3p-c]8)+dYxQ#b<yf<L|&k1k7()8)+)9*Wsud1q@N@XükmpBlDvH 6^|G?7}'r<BI3T#l8EdGKDG\"H#Gll6BX/9ü./i4s6=XVl\\M:>2fr0 a", margin = "O8e#,$~gwk+Ds8a~o)tzI<-JEuEt,UT-opw\"q)fTEGy9Y9M,b_qUCC&7@-g:!6;x)C}m[öU@\"BANq6MolpelüN 6^_K!%w(aTIüZh\"DSWO:Eag8B?7y9<f=5Wx2I_y.CCUXß=6>%e (+=!yw51<Xh#o=#>9vuG{HtWZäg'2Qyqp{%N", },
