      quarry = { name = "Rachsüchtiges Urtum", verse = { "Im Tal, das das Feuer nahm, wandeln manche der Bäume noch.", "Such unter den verkohlten Urtumen", "das eine, dessen Name eine Antwort auf das Brennen verspricht." }, note = "^VNukc4Ytüz+S%03kq-Bp2(EQ6E<rbPEs`#ie{J_)ut;loRa/-z.b#@_A\\=@#jEC%<SnKZi=&F>yA|2v}LFm) $uh]#v", margin = "^VNumc=pc\"A&1S;7=O%:7h2a8&L|) ]XIsShns|0[Cx!-+cVR8-`He{L.'T9KöOC)<S}TQm5k>Xo?{. {J@yS#}dz\\}N*CK9F%cBP3U!\\C5XFzXH(.$w V+WhG=", },
