    [1443] = {
      riddles = {
        ["desolace-shadowbreak"] = { verse = { "In einer Klamm, verborgen in den südöstlichen Bergen, zwischen Pilzen so hoch wie Bäume,", "betreibt die Burning Blade einen mit Ketten behängten Beschwörungskreis und hält einen Stall.", "Manche der Pferde darin sind noch Pferde. Sei freundlich zu ihnen." }, hint = "Die Shadowbreakklamm, verborgen in den südöstlichen Bergen von Desolace. Ein gefangenes Pferd könnte ein beruhigendes Tätscheln gebrauchen.", danger = "Gefährlich (Beschwörer, Herbeirufer und Leyjäger der Burning Blade, Stufe 38 bis 40)", name = "02!ZsD@^&1N0.g\"AyQ*g", note = "/2wraF@T.CB=!IEGwK$`[QmeX}4+f~ug;u`UHI8C&v<x(H%A+&0&ZWAwo)FnekRx%U.)&ljVJG\"[!>DpMwV}Q;SpmhN0ät?#+4c{\\*CqCUL$,kA2$s-P.>\"O=DZFPzgU%sT%b_L>qNXx8670VBNLqEFPw= %\\b)>S", margin = "B8zX!]CY$K(0*OMPpi\"T/7w0du#/ß&c=u_Q7ad[we04';w~`).1kQ7I#1Jw?Zh}s95 -'vZB?Hf(-89@!ln/!iV\\f7@~RoByA%a\"\\})2aSL}$xf", },
        ["desolace-tethris-aran"] = { verse = { "Nördlich der Festung der Burning Blade liegen die Steine einer Elfenstadt verstreut im Staub.", "Kein Elf hat dort gelebt, seit die Welt zerbrach.", "Die Tiere der Öde haben sie nun. Gönn denen, die diese Mauern bauten, einen Augenblick." }, hint = "Tethris Aran, im Norden von Desolace. Trauere zwischen den Ruinen um die Stadt, die hier stand.", danger = "Bewacht (Basilisken, Skorpide und verhungernde Skelettpfoten, Stufe 30 bis 32)", name = "W0GcU>5D=/|]", note = "W0GcU>5D=/|]0:=C?QpR~kp=w)Pnjqg+g3gd1PCyuZN*W\"q0R ek+E9q9'M.Q_PWQlICA%lC,[RStl/YHVX{_Z~=F[s#&d?E[#;*t$:", margin = "Z0<oHGAö00[_}AYB3+Qzk+3a)fSfsaJaQhY Q]~[ua,ar,7['ZT'Wk93#NHXN>gKNgC<5sK.u35*_<C\\_Xvy(wAWjju;R,=NhI*p/sZCj$s~z", },
