        ["feralas-the-maul"] = { verse = { "Zwischen den Ruinen der alten Elfenstadt im Wald haben die Oger eine Grube,", "und Kämpfer springen hinein, um sich dem zu stellen, was in den Ring gekommen ist.", "Darüber sieht ein Goblin jedem Kampf zu und brüllt für alle.", "Spring hinein, und biete ihm eine Vorstellung." }, hint = "Das zerfallene Viertel von Düsterbruch: die Grube, die man die Schlägergrube nennt, unter Griniblix' Hochsitz. Spann in der Grube die Muskeln an. Der Goblin will eine Schau, keinen Kampf.", danger = "Gefährlich (die Gordok-Oger, und eine Grube, in der jeder gegen jeden kämpfen kann)", name = "3d'm!e}.äz^?'[r0]", note = "3d'm!e}.äz^?'[r0];|G.zsfK67X.-M^Ckz6'l(x)#]f+PJüR\\d,6@oCX2?Y-] aU|GEm8fj'<;;EQrdV/>Q|:E%7[Mü1+52VyzCQ4az0)PCeg}'if+.wt 4>Q*eF?sB", margin = "Bf#`@\"y'qVhg/%ct7fv_D7z ;N.9qx{Rv?k&5y_X^9$Fd,8&löVm~BMcNoj%R>Ki)J3DKx9b`5W-.4}-BiACPw<RpBgHgMN93j@XßS:kP-äntXu2SaA$xg,qKG(XhPh*q&Waqkr^8R@jKD#u2A5JU<px3toV>|>,@Z:%?6C2hssDp", },
