    [1446] = {
      riddles = {
        ["tanaris-gadgetzan"] = { verse = { "Finde in der Goblinstadt der Wüste eine Tochter, die den Frieden wählte, den ihr Vater brechen wollte.", "Ihr Streit überquerte einen Ozean, bevor er endete.", "Die Stadt bewahrt den Bericht unter ihren Büchern." }, hint = "Gadgetzan. Lies den Bericht über die Tochter und den Krieg ihres Vaters.", danger = "Ruhig", name = "?/km*7T5CH`se?RjR`@{i.Ts:e`)K--3&'QU{/`?a-O8.h", note = "?/km*7T5CH`se?RjR`@{i.Ts:e`)K--3&'QU{/`?a-O8.h+@gRkntQaHXFL9QeYW !fu;Ta1+h,~~fib5{62\"+Z@0b%Ytk/.arIt~5 7i2cGF+QeiQ>[[xKtV:{P5]);:)(S,JTB8&+i+wcth/ßs?@PO>al", margin = "C5v{,x~6[TCL\\j[%F~6/m)NzMiV4e$ 2>}@X!öFc)PS*em/rIyGYüUc5S=|eiTr'W452Gßj2~/g\\!w\"&&K3NM#buhxo*4XYävEelq7t,9DDZY[PZMiNtC=y](K/E-C\"9?VKB.lpsS", },
        ["tanaris-winkey"] = { verse = { "Vor dem stillen Strand südlich der Piratenbucht trägt eine kleine Insel eine einzige Gnomin, allein,", "die sich sonnt, als wäre das ganze Meer ihr Garten.", "Sie hat eine Bitte an jeden, der zu ihr hinausschwimmt. Lass dein Gesicht für dich sprechen." }, hint = "Ein Inselchen vor Southbreak Shore, südlich der Lost-Rigger-Bucht. Antworte der sonnenbadenden Gnomin mit einem Zwinkern.", danger = "Bewacht (Brandungsgleiter und Küstenschreiter, Stufe 48, in den Untiefen)", name = "Ku?sIb", note = "Ku?sIbW;e-~g~35i4QG0,rz0i*j;q@Ps>rfV%=80e9QAv9nXcWjM-Aaa5&zu/GQ@(22+/Pv+N\"'_8EVRüßLvy%üßRQ25\\ün1#0at2wpmfjlw<ENSK~Hk6h9hW/SmMpqI(6=j+Dxk`0^Gn9", margin = "Kq:|c`1# -~\"cQ9yhZ>~9k|/e*j-p?Az; h[j]01 2WG1%fGfLjc,K:hEzv#7GU9{(Apx8N.Kz7 .(c~\"^<~YyFF`X$MU6{zrv}`2+<[V;g_s|OV\">YZ]A\"U'?n1\\f@8{XtxQPGlgA;(xn,^X=w:T1H{+9_HLy~r]sWH3&(D]Z:", },
        ["tanaris-zalashji"] = { verse = { "Östlich der Stadt der Goblins hat ein Naga einen Bau in den Felsen", "und will überhaupt nichts von dir: keinen Krieg, keinen Schatz, kein Blut.", "Sei ausnahmsweise freundlich." }, hint = "Zalashjis Bau, östlich von Gadgetzan. Verbeuge dich vor dem Naga. Er ist bereit, dich in Ruhe zu lassen.", danger = "Bewacht (Banditen der Wüstenläufer und Stahlkieferschnapper in der Nähe)", name = "(pTcfe m", note = "(pTcfe mzy.e^9>-&&'[oms+$)yPx7%E|k C-5`bebasQ8wjHfVpliw1s=<D h6Zl6U,wZ*=6lLb)|mo *X\\ID6TDSj@R", margin = "u~ZfX|+rSyih\\#Q:9DföfbH13mW^7y.nx$6ßF/$b6VP.waFkQ{){m6g&HWzh0@eSp$qW;R,5BU+'%U(*>`V+2MA[xA3]WC", },
