      quarry = { name = "Omgorn der Verirrte", verse = { "Die Oger der südlichen Wüste halten drei Lager zwischen alten Trollruinen.", "Ein Oger mit einer großen Axt kann in jedem von ihnen sein.", "Den Verirrten nennen sie ihn. Gesellschaft hat er genug, wo immer er auftaucht." }, note = "8C9`ESF)j74*h@7?_;|MXBiy0IgfaC0j8a\\üwBIqIBOog9bb+s8xN{(FNg=s77VOl%.FqüKJja?w>(,V_w[EJe'%2IlrpTqCr q0M\"_Ug(V;PNl0@L85V-UfD7P wXwY;l(%N-", margin = "<;;_8dg=yD(7k:äT;7xNKdp~& eX)Kx/E!tPnOZW<FX|p.VZ+j}7Ok,PNg^", },
