    [1447] = {
      riddles = {
        ["azshara-lake-mennar"] = { verse = { "Im Süden des alten Landes der Elfen halten Drachkin des blauen Schwarms die Ufer eines Sees,", "fern dem kalten Norden, in den ihresgleichen gehört.", "Innerhalb ihres Rings ist der See selbst ruhig. Komm an ihnen vorbei und erfrisch dich am Wasser." }, hint = "Der Mennarsee, im Süden von Azshara. Setz dich eine Weile ans Wasser.", danger = "Gefährlich (die blauen Drachkin rund um den See, Stufe 50 bis 53)", name = "ri(~6/2|W", note = "ii,0\"\"-&S\" s.'nz\"2s?s[f-}Vn[N\\mhvF)8l@yRl~%;_&1[02X*L4]\\HfRyPR2lir#\"SJRCUZD :)`y~s/++DEiVI{$T:pw\"oy`']öSgNyW]q9hjiwqz6i4\\\"%liBt#Ni{WN$", margin = "re4%=,1!^#,VöWEz?}Cb7K5)bhdSMwpx9C=V;xhc#sKx8$9%Ui!]zoZ?kE|VFv%{+{)=VEFo,7k/-F;1o.=yJCjq7eß:pqcwvm}^3'/rTtYcpX", },
        ["azshara-ravencrest"] = { verse = { "Auf den südlichen Klippen stehen noch die zerbrochenen Beine einer großen Statue,", "der Rest verstreut oder unter dem Meer.", "Sie bewahrt den Namen eines Lords, der sich der Königin dieser Küste", "und ihren Dämonen entgegenstellte, als die Welt zerbrach. Finde, was von ihm übrig ist." }, hint = "Das Ravencrest-Monument, auf den südlichen Klippen von Azshara.", danger = "Bewacht (Naga)", name = "#J++tR1RC&y<~}^ZJeD", note = "tJ(EXP5R>t_T#$u:TeEc\\fz0ZSC,_2G67?3>s+SV4bVZNCmy;X\"lQM%ibItY", margin = "|X'*&:4_V&N[~#h?Fm5dZjkuO/@üLXC;?4J'a`QyelY4cwe?g)ZDczg]S^5\\+_?9p<n37FBM'Jd~Xzgpnv(hgUVQtFrr%sO#3H>oO@D>M|-]Q5b)U:FkEvVög(P=x]^Q5_8o#2t-=#xZZgW^zO;bX.oF", },
