        ["silithus-glibb"] = { verse = { "Im Süden der Wüste wartet ein Affe im Sand,", "der Gefährte des berühmtesten Forschers der Zwerge.", "Der Forscher selbst ist nirgends zu sehen. Sei freundlich zu dem Affen." }, hint = "Im Süden von Silithus, östlich des Skarabäuswalls. Ein Winken genügt, um dich dem Affen vorzustellen.", danger = "Gefährlich (die Silithiden nahe der Mauer)", name = "tag7p", note = "tag7p%>.d(fim&eWd!C3o)p#S$\"*T$&2:%T39~X?=YEQvu mgCIuu#et_S-UJKvü#R _Zrgj-mQ", margin = "{^cBog#k[5wNWP\\\\^{QP})e3k$Q8Gy Hv%T;A94%@UA9l{1q[ud", },
