        ["silithus-scarab-wall"] = { verse = { "Am südlichen Ende der gelben Wüste steht eine Mauer,", "errichtet, als die Nachtelfen ihren Krieg gegen die Insekten nicht allein gewinnen konnten,", "und ein Drache der Zeit versiegelte sie. Ein Gong hängt davor.", "Finde die Mauer, und lass den Gong in Ruhe." }, hint = "Der Skarabäuswall, am südlichen Rand von Silithus.", danger = "Gefährlich (die Silithiden)", name = "jJk9K$|XhDä:Q2{XU", note = "jJk9K$|XhDä:Q2{XU\\tew&5;$oY8W^3r6[7y#VL<W3", margin = "|Tk9ly1YlPd5n?#-QWP`Qv'$y j8f?UDi!`U'(LW@Mw2r4Qu1äFj5^n[)'FmrqDNdeX vkl9%<Gs]y[fpB){m 2$ww)]-Uüq8.Ww[cF.ObU~tq@N\\as$hEUnyySWH>]W]b{9I:b)\"pcD2P~xfDEL]MptiU%]xrj\\s]N+ls@(\\lA$ü\"LuM8x[Q.YTK$/ v69lJxK}ßd5{", },
