        ["stormwind-city-khadgar-plaque"] = { verse = { "Unter den Gedenktafeln für jene, die durch das dunkle Tor gingen,", "hält eine ihren Helden für tot und wünscht ihm dann alles Gute auf seinen Reisen.", "Füge dem eingemeißelten Wunsch deinen eigenen hinzu, für einen Wanderer, der vielleicht doch noch heimkehrt." }, hint = "Unter den Gedenktafeln für die Expedition der Allianz, in der Stadt. Wünsche dem abwesenden Reisenden an seinem Denkmal Glück.", danger = "Ruhig", name = "/Y^'hMh*F%'PQ#;^vDI,za2v,T3r7gS5Pha", note = "/Y^'hMh*F%'PQ#;^vDI,za2v,T3r7gS5PhaGfHpX+fq3C):T}xd]6}w V5y", margin = "p5S|oem.9%DId>Gfg-R'qO/ \"T[xDqJ\"^lcyV5:\\'l{%@.J`c$dv|v}5g}b27wdl:=V3dT n hK.v:Du8=D\"7~KxbY@üz*ucK3nWp#8TvW3fAk\"lT=,ipüPW#sD]w1J|@`hKZeN'Y!N9?u$o@xw_WwT<!&%egCc2\\:MvpknOy+gB&Iuvl!25:Rqf.xt89)dDn", },
