        ["ironforge-great-forge"] = { verse = { "Im Herzen der Stadt der Zwerge, bei der großen Schmiede, die ihr den Namen gibt,", "wartet der Hüter der Schmiede auf Schmiede, die gut genug sind, um zu hören, was er zu sagen hat:", "dass ein Schmied einen Weg wählen muss, und niemals den anderen. Frag ihn." }, hint = "Die Große Schmiede, im Herzen von Ironforge. Sprich mit dem Hüter der Schmiede. Seine Lektionen können warten.", danger = "Ruhig", name = "Zj4\"QNb`%?`A!W)}[", note = "Zj4\"QNb`%?`A!W)}[^SFü#c;oK\\s!+a>ß'*e\\,s)0(>VeHq9^II0/kz3bQöd^VaqgZ7tr`\"GJg<q+UGiS;<K\\W (skFCV;RW*s\\/*hq@`\\V#5A>NAN{-28>e}ü~!E`}3:c%`$I.QOj", margin = "454xJ[Vrx5{Csht}PGm}L^p_5Tf@isc4D1tA\"ü;+!01?_K-PQfFEy<k\"M:KT]uUPV<bP!kaWpaIZ+#NhQö;p@w;yz/j<)r?k63y\\/*`q?qW>3?E1NTRrq3EJXüNvsä%'0g<`{G2C0q1&%H0AQZITp.Mgg~D_1L42ss5>^>{v7K2\"S8&]RRv^@1k'L/=ZGCcYx], e!~UTrGü%s~u7/;<*U*Nnh30V,Z&\\/Fd k1Wlu", },
