        ["ironforge-tyrannistrasz"] = { verse = { "Nachdem Grim Batol gefallen war, gab das Sumpfland die Überreste von etwas Gewaltigem frei,", "und die Zwerge brachten sie heim, damit ihre Forscher sie zeigen konnten.", "Die Geschichte sagt, dass es zu Lebzeiten an der Seite einer Königin flog,", "als der älteste ihrer Gefährten. Erfahre, wem sie gehörten." }, hint = "Die Halle der Forscher. Lies die Inschrift beim Schädel.", danger = "Ruhig", name = "VF;xJ+6ä*~G=GAoxLm+?Wx4D`}@%&", note = "VF;xJ+6ä*~G=GAoxLm+?Wx4D`}@%&s", margin = "eF2g\\GÜk+,M#VPaxoi+BNxJ<a}Y1yGd+8X4\"hfDHg^`qiZ$_)/`7H*G'p\\X(yhEP8qe^HK\\MS]HZHbB=x/A6*!2M8}f'1P`DW|emeUXrwjF$NruTiLA=%t4;W`Axb`obypeX7?9^\"", },
