        ["undercity-kelthuzad-book"] = { verse = { "Such in der Stadt unter den Ruinen einen Prediger, dessen Meister aus dem gefrorenen Norden sprach.", "Er versprach den Armen Gleichheit und ein Leben, das nie enden würde.", "Die Geschichte seiner Gemeinde steht unter den Büchern der Kräuterkundigen." }, hint = "In Undercity, bei den Kräuterkundigen: der Laden der Alliestars. Lies das Buch über den Prediger und seinen Kult.", danger = "Ruhig", name = ",oc3|zcN+B,'1H1`SGANMDk1ln;n?&.%T0~?ß-^", note = ",oc3|zcN+B,'1H1`SGANMDk1ln;n?&.%T0~?ß-^$y*W*~NYüX@tpl#|$]11u6/Tt}ü7#~LydA1_CL= F84_YkkE)6{l.q&p&tgR@U[v.H/x_67]#`ij4ss,=:EN7F6H_]YBT^[9*3ScE&L[QW-@#gNV2t_~H'eMxG.`lh5-\\Y'>@?hCW5De/(I'|ßi;[", margin = "gOj,/{S@I)q}I8yql5&)üZ\"yx7s#*.!9h&;,D0f\"yJ[|rMZluY@n+gS*nbB/u4%:{E7v.-9~!FR.V2!,xD8qü^|E)Q{m@a\"uy=WN-p]i'y0f[+<bxi L2ozb#3VK&W#?con+eai99:M_=&LO%V,<whJaIos)Kls_g6?`csZN", },
