        ["zephras-isle-gustjumpers"] = { verse = { "Östlich der Menhire am südlichen Rand des Hochlands", "hüpfen die kleinen Frösche der Insel durchs Gras.", "Zwei von ihnen haben sich der Musik verschrieben.", "Sei ihr Publikum." }, hint = "Zwischen den Menhiren der Warte und dem Böenbeerentiefland, zwischen den Böenspringern. Applaudiere einem der beiden musikalischen Frösche.", danger = "Bewacht (Banditen, Rudelkrallen und Windschreiter in der Nähe, Stufe 5 bis 10)", name = "reE2Lx7vt_`z-'*öY?<il[:>Wc", note = "iY7HN->vl]d~.jP)~srö_`?GdZ&q5r}V[VUn(3:öU='wL;A={-_(2FmDxr/Ba*Frq-Uh1)ö]uUC6:qK>nöi/\"*8P3Ls@[0zuwgP4 vo5H1=%p{bpDr<[#;a.;R$T149[(V}hwho0%A;w<rRGZg^LA}W.", margin = "iY7HH|Bödf\"$jP)~srö_`?GdZ&q5rcBBM^%uN6iWCA$!ZDu8aR\\|38q?xJ6Ae#,!,-?d4&d\"9pNY{@ B+L3ä)z.EZ.J.Hb$dh{h?O\\$UEM'(*7", },
        ["zephras-isle-swimmers"] = { verse = { "Im Gasthaus der Hafenstadt der Insel beteuert ein Seemann ohne Schiff", "dem Wirt, laut und oft, dass er gesehen hat, was er gesehen hat.", "Niemand im Raum glaubt ihm ein Wort.", "Stell dich auf seine Seite." }, hint = "Das Gasthaus in Valanaar. Nicke zur Geschichte des Seemanns. Sonst tut es niemand.", danger = "Ruhig", name = "=Owc'i{dhtTGK5cl_jj*+P9@g/?@\\fM", note = "=Owc'i{dhtTGK5cl_jj*+P9@g/?@\\fMh,F=@|5K+E*<\"VfU>1s.7%1kjpo[sl5BhnVWWe0bw>$F<eZLPjb.R{qCIXk2[a[v/\\d_ \"s[$)@|)@UNHU3NKwa%avITA|D%k`lo`^d3V(J>&nq(,$H )k+tNem%HDS\\|,ö[{f`0/Zu_@7nsRJ`v7$>+KBk4TLII\"Egih;^M@", margin = "AGxs)x:IV4e^;1idb]W*@=:3oIU5`mt\\#QEMT:P*EX8'`fQ?#0l32;kYilWr5L4[[VYNOZhiKCW![Kf<so}R^q,Rö#Db^ /wb^m':h0097%5^_<V6YOl^,\\N2DF8kvyg]un`d9Jv#N+w#[)'Ll(|D", },
